<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Subject; use Illuminate\Http\Request;
class SubjectController extends Controller { public function index(){return view('admin.subjects.index',['subjects'=>Subject::orderBy('name')->paginate(15)]);} public function create(){return view('admin.subjects.create');} public function store(Request $request){$v=$request->validate(['name'=>'required|string|max:100','code'=>'required|string|max:20|unique:subjects,code']);Subject::create($v);return redirect()->route('admin.subjects.index')->with('success','Mapel berhasil ditambahkan.');} public function edit(Subject $subject){return view('admin.subjects.edit',compact('subject'));} public function update(Request $request,Subject $subject){$v=$request->validate(['name'=>'required|string|max:100']);$subject->update(['name'=>$v['name']]);return redirect()->route('admin.subjects.index')->with('success','Mapel berhasil diperbarui.');} public function destroy(Subject $subject){$subject->delete();return redirect()->route('admin.subjects.index')->with('success','Mapel berhasil dihapus.');} }
